function PhaseSelect({ state, toggleDie, confirmSelect }) {
    const { dice, actionIdx } = state;
    const ap = actionIdx.length === 2 ? dice[actionIdx[0]] + dice[actionIdx[1]] : null;

    return (
        <div className="flex flex-col items-center gap-5 py-4">
            <div>
                <p className="text-center text-xs font-semibold uppercase tracking-widest text-amber-400/70 mb-1">
                    주사위 선택
                </p>
                <p className="text-center text-xs text-slate-400">
                    행동 주사위 2개를 고르세요 (합계 = AP)
                </p>
            </div>
            <div className="flex justify-center gap-6">
                {dice.map((v, i) => (
                    <div key={i} className="flex flex-col items-center gap-1">
                        <DieFace
                            value={v}
                            selected={actionIdx.includes(i)}
                            dimmed={actionIdx.length === 2 && !actionIdx.includes(i)}
                            onClick={() => toggleDie(i)}
                        />
                        <span className="text-[10px]" style={{ color: actionIdx.includes(i) ? '#fbbf24' : '#6b5090' }}>
                            {actionIdx.includes(i) ? '행동' : '—'}
                        </span>
                    </div>
                ))}
            </div>
            {ap !== null && (
                <div className="flex items-center gap-2 px-5 py-2.5 rounded-2xl" style={{ background: '#16082e', border: '1px solid #4c1d95' }}>
                    <span className="text-lg text-amber-400">⚙</span>
                    <span className="text-lg font-black text-amber-300">AP {ap}</span>
                </div>
            )}
            <button
                onClick={confirmSelect}
                disabled={actionIdx.length !== 2}
                className="px-8 py-3 rounded-2xl font-bold text-sm transition-all active:scale-95 disabled:opacity-30"
                style={{ background: actionIdx.length === 2 ? 'linear-gradient(135deg,#9333ea,#c026d3)' : '#1a0f2e' }}
            >
                확인 →
            </button>
        </div>
    );
}

function PhaseAction({ state, doAction, toggleCombine, startConstruction, selectBuilding, cancelConstruction, startBuildingSetup, selectProduceBuilding, selectConnection, endActions }) {
    const remaining = state.apPool - state.apUsed;
    const { construction } = state;
    const slots = state.dieSlots || [];
    const allUsed = slots.length > 0 && slots.every(s => s.used);
    const unusedCount = slots.filter(s => !s.used).length;

    // 생산 건물 선택 화면
    if (state.pendingProduce) {
        const { buildingType, buildingTypes, amt } = state.pendingProduce;
        const typeList = buildingTypes || (buildingType ? [buildingType] : []);
        const targets = Object.entries(state.buildings).filter(([, b]) => typeList.includes(b.type) && b.active);
        const resIcon = { food_plant: '🍖', oxygen_plant: '💨', cryo_tank: '❄️', research_site: '🧠', rover: '🧠' }[typeList[0]] ?? '📦';
        const def = BUILDINGS[typeList[0]];
        return (
            <div className="flex flex-col gap-3 py-4">
                <div className="px-1">
                    <p className="text-xs font-semibold uppercase tracking-widest text-green-400/70">
                        생산 대상 건물 선택 (+{amt})
                    </p>
                    <p className="text-xs text-white/40 mt-0.5">{resIcon} {def?.name} — 자원을 저장할 건물을 선택하세요</p>
                </div>
                <div className="flex flex-col gap-2">
                    {targets.map(([hexKey, bld]) => {
                        const bldDef = BUILDINGS[bld.type];
                        const storeCap = bldDef?.storeCap || 0;
                        const current = bld.store || 0;
                        const space = storeCap - current;
                        const willAdd = Math.min(amt, space);
                        const overflow = amt - willAdd;
                        return (
                            <button key={hexKey} onClick={() => selectProduceBuilding(hexKey)}
                                className="flex items-center justify-between px-3 py-2.5 rounded-xl transition-all active:scale-[0.98] hover:brightness-110"
                                style={{ background: '#0f2a1a', border: '1px solid #16a34a' }}>
                                <div className="flex items-center gap-2">
                                    <span className="text-sm font-semibold text-white">{bldDef?.name}</span>
                                    <span className="text-xs text-white/40">[{hexKey}]</span>
                                </div>
                                <div className="flex items-center gap-2 text-xs">
                                    <div className="flex gap-0.5">
                                        {Array.from({ length: storeCap }, (_, i) => (
                                            <div key={i} className="w-2.5 h-2.5 rounded-sm"
                                                style={{ background: i < current ? '#16a34a' : i < current + willAdd ? '#86efac' : '#1f2937' }} />
                                        ))}
                                    </div>
                                    <span className="text-green-400">+{willAdd}</span>
                                    {overflow > 0 && <span className="text-amber-400">(+{overflow} depot)</span>}
                                </div>
                            </button>
                        );
                    })}
                </div>
            </div>
        );
    }

    // 연결 대상 선택 화면 (냉동탱크 → 플랜트, 재활용기 → 분리기)
    if (state.pendingConnection) {
        const { hexKey, candidates } = state.pendingConnection;
        const bld = state.buildings[hexKey];
        const isRecycler = bld?.type === 'recycler';
        const targetTypeName = isRecycler ? '분리기' : '플랜트';
        return (
            <div className="flex flex-col gap-3 py-4">
                <div className="px-1">
                    <p className="text-xs font-semibold uppercase tracking-widest text-cyan-400/70">
                        연결 대상 선택
                    </p>
                    <p className="text-xs text-white/40 mt-0.5">
                        {BUILDINGS[bld?.type]?.name} [{hexKey}] 를 연결할 {targetTypeName}를 선택하세요
                    </p>
                </div>
                <div className="flex flex-col gap-2">
                    {candidates.map(cKey => {
                        const cBld = state.buildings[cKey];
                        const cDef = BUILDINGS[cBld?.type];
                        return (
                            <button key={cKey} onClick={() => selectConnection(cKey)}
                                className="flex items-center justify-between px-3 py-2.5 rounded-xl transition-all active:scale-[0.98] hover:brightness-110"
                                style={{ background: '#0a1f2e', border: '1px solid #0891b2' }}>
                                <div className="flex items-center gap-2">
                                    <span className="text-sm font-semibold text-white">{cDef?.name}</span>
                                    <span className="text-xs text-white/40">[{cKey}]</span>
                                </div>
                                <span className="text-xs text-cyan-400">연결 →</span>
                            </button>
                        );
                    })}
                </div>
            </div>
        );
    }

    // 헥스 선택 화면 (일반 건설 or 분리기/재활용기 설치)
    if (construction?.step === 'place' || construction?.step === 'place_setup') {
        const def  = BUILDINGS[construction.buildingType];
        const isSetup = construction.step === 'place_setup';
        return (
            <div className="flex flex-col gap-3 py-4">
                <div className="flex items-center justify-between px-1">
                    <p className="text-xs font-semibold uppercase tracking-widest text-green-400/70">
                        {isSetup ? '설치 위치 선택 (1단계)' : '배치 위치 선택'}
                    </p>
                    <button onClick={cancelConstruction}
                        className="text-xs text-white/40 hover:text-white px-2 py-1 rounded-lg bg-white/5 transition-all">
                        ← 취소
                    </button>
                </div>
                <div className="px-3 py-3 rounded-xl" style={{ background: '#1e0f38', border: '1px solid #5b21b6' }}>
                    <div className="flex items-center justify-between">
                        <span className="font-bold text-white">{def?.name}</span>
                        <div className="flex items-center gap-1 text-xs text-amber-300">
                            {isSetup
                                ? <span>⚙{def?.stepCost} × {def?.setupSteps}단계</span>
                                : <>
                                    <span>⚙{def?.cost?.g}</span>
                                    {(def?.cost?.m || 0) > 0 && <span>🔩{def.cost.m}</span>}
                                    {(def?.cost?.p || 0) > 0 && <span>⚡{def.cost.p}</span>}
                                </>
                            }
                        </div>
                    </div>
                    <p className="text-xs text-purple-300/70 mt-0.5">{def?.effect}</p>
                </div>
                <p className="text-xs text-green-400/70 text-center animate-pulse">
                    ↓ 아래 지도에서 초록색 헥스를 선택하세요
                </p>
            </div>
        );
    }

    // 1단계: 건물 선택
    if (construction?.step === 'select_building') {
        const recyclerMats = Object.values(state.buildings).filter(b => b.type === 'recycler').reduce((s, b) => s + (b.store || 0), 0);
        const localPower   = Object.values(state.buildings).filter(b => b.type === 'nuclear_pod' || b.type === 'amplifier').reduce((s, b) => s + (b.store || 0), 0);
        const ctx = { buildings: state.buildings, roverBuilt: state.roverBuilt, apRemaining: remaining, materials: state.materials + recyclerMats, power: state.power + localPower };
        const buildableTypes = Object.keys(BUILDINGS).filter(t => BUILDINGS[t].cost);
        return (
            <div className="flex flex-col gap-3 py-4">
                <div className="flex items-center justify-between px-1">
                    <p className="text-xs font-semibold uppercase tracking-widest text-amber-400/70">건물 선택</p>
                    <button onClick={cancelConstruction}
                        className="text-xs text-white/40 hover:text-white px-2 py-1 rounded-lg bg-white/5 transition-all">
                        ← 취소
                    </button>
                </div>
                <div className="flex flex-col gap-1.5 max-h-56 overflow-y-auto">
                    {buildableTypes.map(type => {
                        const def = BUILDINGS[type];
                        const cost = def.cost;
                        const hasValid = generateHexGrid(MAP_RADIUS).some(({ q, r }) => canPlaceBuilding(ctx, type, q, r));
                        return (
                            <button key={type} onClick={() => hasValid && selectBuilding(type)} disabled={!hasValid}
                                className={`flex flex-col px-3 py-2 rounded-xl text-left transition-all ${hasValid ? 'hover:brightness-110 active:scale-[0.98]' : 'opacity-30'}`}
                                style={{ background: hasValid ? '#1e0f38' : '#12082a', border: `1px solid ${hasValid ? '#5b21b6' : '#2d1a52'}` }}>
                                <div className="flex items-center justify-between">
                                    <span className="text-sm font-semibold text-white">{def.name}</span>
                                    <div className="flex items-center gap-1 text-xs text-amber-300">
                                        <span>⚙{cost.g}</span>
                                        {(cost.m || 0) > 0 && <span>🔩{cost.m}</span>}
                                        {(cost.p || 0) > 0 && <span>⚡{cost.p}</span>}
                                    </div>
                                </div>
                                <div className="flex items-center gap-2 mt-0.5">
                                    {def.terrain !== 'any' && (
                                        <span className="text-[10px] px-1.5 py-0.5 rounded" style={{
                                            background: def.terrain === 'trash' ? '#3b200a' : def.terrain === 'ice' ? '#062030' : '#161020',
                                            color: def.terrain === 'trash' ? '#a16207' : def.terrain === 'ice' ? '#0891b2' : '#7c3aed',
                                        }}>
                                            {def.terrain === 'trash' ? '♲' : def.terrain === 'ice' ? '❄' : '◉'}
                                        </span>
                                    )}
                                    <span className="text-[10px] text-purple-300/60 truncate">{def.effect}</span>
                                </div>
                            </button>
                        );
                    })}
                </div>
            </div>
        );
    }

    // 일반 행동 단계
    const hasBuildingOfType = (type) => {
        if (Array.isArray(type)) return type.some(t => Object.values(state.buildings).some(b => b.type === t && b.active));
        return Object.values(state.buildings).some(b => b.type === type && b.active);
    };

    return (
        <div className="flex flex-col gap-3 py-4">
            {/* 주사위 슬롯 표시 */}
            <div className="flex items-center justify-between px-1">
                <p className="text-xs font-semibold uppercase tracking-widest text-amber-400/70">행동 단계</p>
                <div className="flex items-center gap-1.5">
                    {state.combineMode ? (
                        <div className="flex items-center gap-1 px-2.5 py-1.5 rounded-xl"
                             style={{ background: '#16082e', border: '1px solid #7c3aed' }}>
                            <span className="text-[10px] text-purple-300/60">합산</span>
                            <span className="font-black text-amber-300 ml-1">{slots.reduce((s, sl) => s + sl.ap, 0)}</span>
                            <span className="text-[10px] text-white/40 ml-0.5">⚙</span>
                        </div>
                    ) : (
                        slots.map((slot, i) => (
                            <div key={i} className="flex items-center gap-1 px-2.5 py-1.5 rounded-xl"
                                 style={{
                                     background: slot.used ? '#0d0618' : '#16082e',
                                     border: `1px solid ${slot.used ? '#1f0f3a' : '#7c3aed'}`,
                                     opacity: slot.used ? 0.45 : 1,
                                 }}>
                                {slot.used
                                    ? <span className="text-xs text-green-400">✓</span>
                                    : <span className="font-black text-amber-300">{slot.ap}</span>
                                }
                                <span className="text-[10px] text-white/40">⚙</span>
                            </div>
                        ))
                    )}
                    {slots.length === 2 && !slots.some(s => s.used) && (
                        <button onClick={toggleCombine}
                            className="text-[11px] px-2 py-1.5 rounded-lg transition-all active:scale-95"
                            style={{ background: '#1a0f30', border: '1px solid #3b1e6b', color: '#a78bfa' }}>
                            {state.combineMode ? '분리' : '합산'}
                        </button>
                    )}
                </div>
            </div>

            <div className="flex flex-col gap-1.5">
                {ACTIONS.map((act) => {
                    // 필요 건물 없으면 숨김
                    const reqB = act.reqBuilding || act.reqBuildings;
                    if (reqB && !hasBuildingOfType(reqB)) return null;

                    if (act.id === 'construction') {
                        const canStart = remaining > 0;
                        return (
                            <button key={act.id} onClick={() => canStart && startConstruction()} disabled={!canStart}
                                className={`flex items-center justify-between px-3 py-2.5 rounded-xl transition-all active:scale-[0.98] ${canStart ? 'hover:brightness-110' : 'opacity-25'}`}
                                style={{ background: canStart ? '#1e1030' : '#12082a', border: `1px solid ${canStart ? '#5b21b6' : '#2d1a52'}` }}>
                                <span className="text-sm font-semibold text-white">{act.label}</span>
                                <span className="text-xs text-purple-300">건물 건설 →</span>
                            </button>
                        );
                    }

                    // setup_separator / setup_recycler — 다단계 설치 버튼
                    if (act.id === 'setup_separator' || act.id === 'setup_recycler') {
                        const bType = act.id === 'setup_separator' ? 'separator' : 'recycler';
                        const def   = BUILDINGS[bType];
                        const inProgress = Object.values(state.buildings).find(b => b.type === bType && !b.active);
                        const stepNow    = inProgress ? (inProgress.setupStep || 1) : 0;
                        const canAdvance = !!inProgress && remaining >= act.apCost;
                        const canPlace   = !inProgress && remaining >= act.apCost;
                        const canAny     = canAdvance || canPlace;
                        return (
                            <div key={act.id} className="px-3 py-2 rounded-xl"
                                style={{ background: canAny ? '#1e0f38' : '#12082a', border: `1px solid ${canAny ? '#5b21b6' : '#2d1a52'}`, opacity: canAny ? 1 : 0.4 }}>
                                <div className="flex items-center justify-between">
                                    <span className="text-sm font-semibold text-white">{act.label}</span>
                                    <span className="text-[10px] text-purple-300/60">
                                        {inProgress ? `${stepNow}/${def.setupSteps}단계` : `${def.setupSteps}단계 필요`}
                                        <span className="ml-1 text-amber-400">⚙{act.apCost}</span>
                                    </span>
                                </div>
                                {inProgress && (
                                    <div className="flex gap-1 mt-1.5 mb-1">
                                        {Array.from({ length: def.setupSteps }, (_, i) => (
                                            <div key={i} className="flex-1 h-1.5 rounded-full"
                                                style={{ background: i < stepNow ? '#7c3aed' : '#2d1a52' }} />
                                        ))}
                                    </div>
                                )}
                                <button
                                    onClick={() => canAdvance ? doAction(act.id) : canPlace && startBuildingSetup(bType)}
                                    disabled={!canAny}
                                    className={`w-full mt-1 py-1.5 rounded-lg text-xs font-semibold transition-all active:scale-95 ${canAny ? 'hover:brightness-110' : 'opacity-30'}`}
                                    style={{ background: canAny ? '#2d1a52' : '#1a0f2e', border: `1px solid ${canAny ? '#7c3aed' : '#2d1a52'}`, color: '#c4b5fd' }}>
                                    {canAdvance ? '다음 단계' : canPlace ? '새로 설치' : '불가'}
                                </button>
                            </div>
                        );
                    }

                    // x2x3 행동 — 인라인 ×1 / ×2 / ×N 버튼 (apPerMult, maxMult 반영)
                    if (act.x2x3) {
                        const apPerMult  = act.apPerMult || 2;
                        const maxMult    = act.maxMult   || 3;
                        const separatorStore = act.id === 'recycle'
                            ? Object.values(state.buildings).reduce((s, b) => b.type === 'separator' ? s + (b.store || 0) : s, 0)
                            : Infinity;
                        const anyAffordable = remaining >= apPerMult && (act.id !== 'recycle' || separatorStore >= 1);
                        const multLabel = Array.from({ length: maxMult }, (_, i) => `×${i+1}`).join('/');
                        return (
                            <div key={act.id} className="px-3 py-2 rounded-xl"
                                style={{ background: anyAffordable ? '#1e0f38' : '#12082a', border: `1px solid ${anyAffordable ? '#5b21b6' : '#2d1a52'}`, opacity: anyAffordable ? 1 : 0.3 }}>
                                <div className="flex items-center justify-between mb-1.5">
                                    <span className="text-sm font-semibold text-white">{act.label}</span>
                                    <div className="flex items-center gap-2">
                                        {act.id === 'recycle' && (
                                            <span className="text-[10px] text-amber-400/60">분리기 {separatorStore}개</span>
                                        )}
                                        <span className="text-[10px] text-purple-300/60">{act.desc} [{multLabel}]</span>
                                    </div>
                                </div>
                                <div className="flex gap-1.5">
                                    {Array.from({ length: maxMult }, (_, i) => i + 1).map(mult => {
                                        const cost = mult * apPerMult;
                                        const canDo = remaining >= cost && (act.id !== 'recycle' || separatorStore >= mult);
                                        return (
                                            <button key={mult} onClick={() => canDo && doAction(act.id, mult)} disabled={!canDo}
                                                className={`flex-1 flex flex-col items-center py-1 rounded-lg transition-all active:scale-95 ${canDo ? 'hover:brightness-110' : 'opacity-30'}`}
                                                style={{ background: canDo ? '#2d1a52' : '#1a0f2e', border: `1px solid ${canDo ? '#7c3aed' : '#2d1a52'}` }}>
                                                <span className="text-xs font-black text-purple-300">×{mult}</span>
                                                <div className="flex items-center gap-0.5 mt-0.5">
                                                    <span className="text-[10px] text-amber-400">⚙</span>
                                                    <span className="text-[10px] text-amber-300">{cost}</span>
                                                </div>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    }

                    // 고정 비용 행동
                    const cost = typeof act.apCost === 'number' ? act.apCost : null;
                    const canAfford = cost !== null && remaining >= cost;
                    return (
                        <button key={act.id} onClick={() => canAfford && doAction(act.id)} disabled={!canAfford}
                            className={`flex items-center justify-between px-3 py-2.5 rounded-xl transition-all active:scale-[0.98] ${canAfford ? 'hover:brightness-110' : 'opacity-25'}`}
                            style={{ background: canAfford ? '#1e0f38' : '#12082a', border: `1px solid ${canAfford ? '#5b21b6' : '#2d1a52'}` }}>
                            <span className="text-sm font-semibold text-white">{act.label}</span>
                            <div className="flex items-center gap-2">
                                {act.desc && <span className="text-xs text-purple-300">{act.desc}</span>}
                                <div className="flex items-center gap-1 px-2 py-0.5 rounded-lg" style={{ background: '#2d1a52' }}>
                                    <span className="text-xs text-amber-400">⚙</span>
                                    <span className="text-xs font-bold text-amber-300">{cost ?? '?'}</span>
                                </div>
                            </div>
                        </button>
                    );
                })}
            </div>

            <div className="mt-1">
                {unusedCount > 0 && (
                    <div className="flex items-center gap-2 px-3 py-2 mb-2 rounded-xl" style={{ background: '#1f0a0a', border: '1px solid #7f1d1d' }}>
                        <AlertCircle size={14} className="text-red-400 shrink-0" />
                        <span className="text-xs text-red-300">미사용 주사위 {unusedCount}개 → 정신력 -{unusedCount} 패널티</span>
                    </div>
                )}
                {allUsed ? (
                    <button onClick={endActions}
                        className="w-full py-3 rounded-2xl font-bold text-sm transition-all active:scale-95"
                        style={{ background: 'linear-gradient(135deg,#0d2e1a,#1a4a2e)', border: '1px solid #16a34a', color: '#86efac' }}>
                        완료 ✓
                    </button>
                ) : (
                    <button onClick={endActions}
                        className="w-full py-3 rounded-2xl font-bold text-sm transition-all active:scale-95 opacity-70"
                        style={{ background: 'linear-gradient(135deg,#1e1030,#2d1a52)', border: '1px solid #5b21b6' }}>
                        행동 종료 →
                    </button>
                )}
            </div>
        </div>
    );
}

function PhaseAccident({ state, setAccidentDie, resolveAccident }) {
    const ad = state.accidentDice || [null, null];
    const leftover = ad[0];   // 행동 단계에서 남겨둔 주사위 (읽기전용)
    const newRoll  = ad[1];   // 사고 단계에 새로 굴리는 주사위
    const sum = (leftover !== null && newRoll !== null) ? leftover + newRoll : null;
    const result = sum !== null ? ACCIDENTS[sum] : null;

    return (
        <div className="flex flex-col items-center gap-5 py-4">
            <div>
                <p className="text-xs font-semibold uppercase tracking-widest text-red-400/70 text-center mb-1">
                    사고 단계
                </p>
                <p className="text-xs text-slate-400 text-center">남겨둔 주사위 + 새 주사위 → 합계 2~12</p>
            </div>
            <div className="flex justify-center gap-8 items-end">
                {/* 남겨둔 주사위 (읽기전용) */}
                <div className="flex flex-col items-center gap-1">
                    <span className="text-xs text-amber-400/70">남겨둔 주사위</span>
                    <DieFace value={leftover} size={64} />
                    <span className="text-[10px] text-white/30">행동 단계에서</span>
                </div>
                <span className="text-2xl text-white/30 pb-4">+</span>
                {/* 새로 굴리는 주사위 */}
                <div className="flex flex-col items-center gap-1">
                    <span className="text-xs text-white/40">새 주사위 굴리기</span>
                    <DieInput value={newRoll} onChange={(val) => setAccidentDie(1, val)} />
                </div>
            </div>
            {sum !== null && (
                <div className="flex items-center gap-2 px-4 py-2 rounded-xl" style={{ background: '#16082e', border: '1px solid #4c1d95' }}>
                    <span className="text-white/60 text-sm">합계</span>
                    <span className="text-xl font-black text-red-300">{sum}</span>
                </div>
            )}
            {result ? (
                <div className="w-full text-center px-4 py-3 rounded-2xl" style={{ background: '#1f0505', border: '1px solid #7f1d1d' }}>
                    <p className="font-bold text-red-300 text-base">{result.label}</p>
                    <p className="text-sm text-slate-300 mt-1">
                        {result.effects.map(({ res, d }) => {
                            const r = [...RES, ...DEPOT].find(x => x.key === res);
                            return `${r?.emoji ?? res} ${d > 0 ? '+' : ''}${d}`;
                        }).join('  ')}
                    </p>
                </div>
            ) : sum !== null ? (
                <p className="text-sm text-slate-400">합계 {sum}: 결과 없음</p>
            ) : null}
            <button
                onClick={resolveAccident}
                disabled={sum === null}
                className="px-8 py-3 rounded-2xl font-bold text-sm transition-all active:scale-95 disabled:opacity-30"
                style={{ background: 'linear-gradient(135deg,#7f1d1d,#991b1b)' }}
            >
                적용 →
            </button>
        </div>
    );
}

function PhaseConsumption({ state, resolveConsumption }) {
    const c = state.consumption;
    const items = c ? Object.entries(c).filter(([, v]) => v !== 0) : [];
    return (
        <div className="flex flex-col items-center gap-5 py-4">
            <p className="text-xs font-semibold uppercase tracking-widest text-orange-400/70">
                자원 소모 (5턴마다)
            </p>
            <div className="w-full flex flex-col gap-2">
                {items.map(([res, v]) => {
                    const r = RES.find(x => x.key === res) || DEPOT.find(x => x.key === res);
                    const isRad = res === 'radiation';
                    return (
                        <div key={res} className="flex items-center justify-between px-4 py-2.5 rounded-xl"
                            style={{ background: '#1a0a00', border: '1px solid #78350f' }}>
                            <span className="font-semibold" style={{ color: r?.color ?? '#fff' }}>
                                {r?.emoji} {r?.label ?? res}
                            </span>
                            <span className="font-black text-sm" style={{ color: isRad ? '#f87171' : '#fb923c' }}>
                                {isRad ? `+${v}` : `-${v}`}
                            </span>
                        </div>
                    );
                })}
            </div>
            <button
                onClick={resolveConsumption}
                className="px-8 py-3 rounded-2xl font-bold text-sm transition-all active:scale-95"
                style={{ background: 'linear-gradient(135deg,#78350f,#92400e)' }}
            >
                적용 →
            </button>
        </div>
    );
}

function PhaseOver({ state, restart }) {
    const { victory, gameOverReason } = state;
    const reasonLabels = {
        food: '식량이 부족합니다',
        oxygen: '산소가 고갈되었습니다',
        sanity: '정신력이 무너졌습니다',
        radiation: '방사선 방호가 소진되어 사망',
        timeout: '75턴을 버티지 못했습니다',
    };
    return (
        <div className="flex flex-col items-center gap-5 py-8 px-4 text-center">
            <div className="text-5xl">{victory ? '🚀' : '☠️'}</div>
            <div>
                <h2 className="text-2xl font-black" style={{ color: victory ? '#4ade80' : '#f87171' }}>
                    {victory ? '임무 완료!' : '임무 실패'}
                </h2>
                {!victory && gameOverReason && (
                    <p className="text-sm text-slate-400 mt-1">{reasonLabels[gameOverReason]}</p>
                )}
                {!victory && (
                    <p className="text-xs text-slate-500 mt-1">턴 {state.turn} / 75</p>
                )}
            </div>
            <button
                onClick={restart}
                className="px-8 py-3 rounded-2xl font-bold text-sm transition-all active:scale-95"
                style={{ background: 'linear-gradient(135deg,#4f46e5,#7c3aed)' }}
            >
                다시 시작
            </button>
        </div>
    );
}

