// Stage lengths: 10 / 15 / 25 / 15 / 10 turns (total 75)
export const CONSUMPTION_STAGES = [
    { food: 1, oxygen: 1, sanity: 0, radiation: 0 },   // turns  1-10
    { food: 1, oxygen: 1, sanity: 1, radiation: 0 },   // turns 11-25
    { food: 1, oxygen: 1, sanity: 1, radiation: 1 },   // turns 26-50
    { food: 1, oxygen: 1, sanity: 2, radiation: 1 },   // turns 51-65
    { food: 1, oxygen: 1, sanity: 2, radiation: 2 },   // turns 66-75
];

export const getConsumptionStage = (turn) => {
    if (turn <= 10) return CONSUMPTION_STAGES[0];
    if (turn <= 25) return CONSUMPTION_STAGES[1];
    if (turn <= 50) return CONSUMPTION_STAGES[2];
    if (turn <= 65) return CONSUMPTION_STAGES[3];
    return CONSUMPTION_STAGES[4];
};

