// Axial hex neighbor directions (flat-top)
const HEX_DIRS = [[1,0],[1,-1],[0,-1],[-1,0],[-1,1],[0,1]];
export const hexNeighbors = (q, r) => HEX_DIRS.map(([dq, dr]) => [q + dq, r + dr]);

// Pure validity check — takes plain args so both reducer and component can use it
export function canPlaceBuilding({ buildings, roverBuilt, apRemaining, materials, power }, type, q, r) {
    const def = BUILDINGS[type];
    if (!def || !def.cost) return false;  // multi-step buildings (sep/rec) use own actions

    const key = `${q},${r}`;
    if (buildings[key]) return false;

    // Outer hex locked
    if (Math.max(Math.abs(q), Math.abs(r), Math.abs(q + r)) === MAP_RADIUS && !roverBuilt)
        return false;

    // Terrain
    const terrain = TERRAIN_MAP[key] || TERRAIN.BLANK;
    if (def.terrain !== 'any' && terrain !== def.terrain) return false;

    // Cryo Tank: adjacent to an AVAILABLE plant (no cryo_tank already connectedTo that plant)
    if (type === 'cryo_tank') {
        const ok = hexNeighbors(q, r).some(([nq, nr]) => {
            const nb = buildings[`${nq},${nr}`];
            if (nb?.type !== 'food_plant' && nb?.type !== 'oxygen_plant') return false;
            const plantKey = `${nq},${nr}`;
            const plantUsed = Object.values(buildings).some(b => b.type === 'cryo_tank' && b.connectedTo === plantKey);
            return !plantUsed;
        });
        if (!ok) return false;
    }

    // Transceiver: must be 3+ hex distance from all other transceivers
    if (type === 'transceiver') {
        const tooClose = Object.entries(buildings).some(([bKey, b]) => {
            if (b.type !== 'transceiver') return false;
            const [bq, br] = bKey.split(',').map(Number);
            const dist = Math.max(Math.abs(q - bq), Math.abs(r - br), Math.abs((q + r) - (bq + br)));
            return dist < 3;
        });
        if (tooClose) return false;
    }

    // Workshop requires laboratory
    if (type === 'workshop') {
        const hasLab = Object.values(buildings).some(b => b.type === 'laboratory');
        if (!hasLab) return false;
    }

    // Costs
    if (apRemaining < (def.cost.g || 0)) return false;
    if ((def.cost.m || 0) > materials) return false;
    if ((def.cost.p || 0) > power) return false;

    // Max count
    if (def.max) {
        const count = Object.values(buildings).filter(b => b.type === type).length;
        if (count >= def.max) return false;
    }

    return true;
}

// Generate all hexes for a radius-R axial hex grid (hexagonal shape, each edge = R+1 hexes)
export const generateHexGrid = (radius = MAP_RADIUS) => {
    const hexes = [];
    for (let q = -radius; q <= radius; q++) {
        const rMin = Math.max(-radius, -q - radius);
        const rMax = Math.min(radius, -q + radius);
        for (let r = rMin; r <= rMax; r++) {
            hexes.push({ q, r });
        }
    }
    return hexes;
};

// Axial coords → pixel (pointy-top hexagons — vertices at 11 & 1 o'clock)
export const hexToPixel = (q, r, size) => ({
    x: size * Math.sqrt(3) * (q + r / 2),
    y: size * (3 / 2) * r,
});

// Pointy-top hex corner points (+30° offset from flat-top)
export const hexCorners = (cx, cy, size) =>
    Array.from({ length: 6 }, (_, i) => {
        const angle = (Math.PI / 180) * (60 * i + 30);
        return [cx + size * Math.cos(angle), cy + size * Math.sin(angle)];
    });
